import os
import numpy as np
import torch


class Config:
    """
    Centralized configuration for the 3D Object Detection Task (PointPillars).
    """

    # ==============================================================================
    # PATHS & DIRECTORIES
    # ==============================================================================
    INPUT_DIR = "./input"
    WORKING_DIR = "./working"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the analysis script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Input Data Subdirectories
    TRAIN_LIDAR_DIR = os.path.join(INPUT_DIR, "train_lidar")
    TEST_LIDAR_DIR = os.path.join(INPUT_DIR, "test_lidar")

    # Output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "model_checkpoint.pth")

    # ==============================================================================
    # DATA SPECIFICATIONS
    # ==============================================================================
    # Random Seed for Reproducibility
    SEED = 42

    # Point Cloud Range: [x_min, y_min, z_min, x_max, y_max, z_max]
    # Selected to cover typical urban driving scenes (approx +/- 50m)
    # Z range covers from below ground to above tall vehicles
    POINT_CLOUD_RANGE = [-51.2, -51.2, -5.0, 51.2, 51.2, 3.0]

    # Voxel Size: [x_size, y_size, z_size]
    # z_size matches the full Z range to create pillars (no vertical partition)
    VOXEL_SIZE = [0.2, 0.2, 8.0]

    # Calculated Grid Size (W, H, D) -> (X, Y, Z)
    GRID_SIZE = [
        int((POINT_CLOUD_RANGE[3] - POINT_CLOUD_RANGE[0]) / VOXEL_SIZE[0]),
        int((POINT_CLOUD_RANGE[4] - POINT_CLOUD_RANGE[1]) / VOXEL_SIZE[1]),
        1,  # Pillars have depth 1
    ]

    # PointPillars Specifics
    MAX_POINTS_PER_PILLAR = 32
    MAX_PILLARS_TRAIN = 16000
    MAX_PILLARS_TEST = 40000

    # Input Feature Dimensions
    # Raw Lidar: x, y, z, intensity (4)
    NUM_INPUT_FEATURES = 4
    # Pillar Feature Net Output Channels
    NUM_PILLAR_FEATURES = 64

    # ==============================================================================
    # CLASS & ANCHOR CONFIGURATION
    # ==============================================================================
    # Class Names ordered by frequency/importance
    CLASS_NAMES = [
        "car",
        "truck",
        "bus",
        "pedestrian",
        "bicycle",
        "other_vehicle",
        "motorcycle",
        "emergency_vehicle",
        "animal",
    ]

    NUM_CLASSES = len(CLASS_NAMES)

    # Anchor Sizes: [width, length, height]
    # Derived from dataset metadata analysis (mean dimensions)
    ANCHOR_SIZES = {
        "car": [1.93, 4.76, 1.72],
        "truck": [2.82, 10.36, 3.46],
        "bus": [2.95, 12.38, 3.42],
        "pedestrian": [0.77, 0.80, 1.77],
        "bicycle": [0.64, 1.75, 1.46],
        "other_vehicle": [2.80, 8.18, 3.24],
        "motorcycle": [1.00, 2.39, 1.52],
        "emergency_vehicle": [2.89, 7.76, 2.97],
        "animal": [0.38, 0.77, 0.57],
    }

    # Anchor Rotations (0 and 90 degrees in radians)
    ANCHOR_ROTATIONS = [0, 1.57]

    # Matching Thresholds for IoU (Positive, Negative)
    ANCHOR_MATCH_THRESHOLDS = {
        "car": (0.6, 0.45),
        "truck": (0.55, 0.4),
        "bus": (0.55, 0.4),
        "pedestrian": (0.5, 0.35),
        "bicycle": (0.5, 0.35),
        "other_vehicle": (0.5, 0.35),
        "motorcycle": (0.5, 0.3),
        "emergency_vehicle": (0.5, 0.35),
        "animal": (0.5, 0.35),
    }

    # ==============================================================================
    # TRAINING HYPERPARAMETERS
    # ==============================================================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Batch Size (A100 40GB can handle larger, but 4 is safe baseline)
    BATCH_SIZE = 4

    # Workers for DataLoader
    NUM_WORKERS = 4

    # Optimization
    LEARNING_RATE = 0.0003
    WEIGHT_DECAY = 0.01
    EPOCHS = 10

    # Gradient Clipping
    GRAD_NORM_CLIP = 10.0

    # Focal Loss Settings
    FOCAL_ALPHA = 0.25
    FOCAL_GAMMA = 2.0

    # Weights for Loss Components
    LOSS_WEIGHTS = {"cls_weight": 1.0, "loc_weight": 2.0, "dir_weight": 0.2}

    # ==============================================================================
    # INFERENCE & POST-PROCESSING
    # ==============================================================================
    # Non-Maximum Suppression
    NMS_IOU_THRESHOLD = 0.1
    NMS_SCORE_THRESHOLD = 0.1
    MAX_PROPOSALS = 500  # Max boxes to keep per sample

    @staticmethod
    def print_config():
        print("=" * 40)
        print("CONFIG")
        print("=" * 40)
        print(f"Device: {Config.DEVICE}")
        print(f"Batch Size: {Config.BATCH_SIZE}")
        print(f"Epochs: {Config.EPOCHS}")
        print(f"Grid Size: {Config.GRID_SIZE}")
        print(f"Voxel Size: {Config.VOXEL_SIZE}")
        print(f"Point Cloud Range: {Config.POINT_CLOUD_RANGE}")
        print(f"Classes: {Config.CLASS_NAMES}")
        print("=" * 40)
